// Renders the sla_report() result as an HTML email for the team lead.
const r = $input.first().json.result;
const t = r.totals;
const esc = (v) => String(v ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const pct = (v) => (v === null || v === undefined ? '—' : `${v}%`);
const num = (v) => (v === null || v === undefined ? '—' : v);

const kpi = (label, value, color = '#111827') =>
  `<td style="padding:10px 18px;border:1px solid #e5e7eb"><div style="font-size:12px;color:#6b7280">${label}</div>
   <div style="font-size:22px;font-weight:bold;color:${color}">${esc(value)}</div></td>`;

const table = (title, list, key, label) => `
<h3 style="margin:20px 0 6px">${title}</h3>
<table cellpadding="6" cellspacing="0" border="1" style="border-collapse:collapse;font-size:13px">
  <tr style="background:#f3f4f6"><th align="left">${label}</th><th>Total</th><th>Open</th><th>At risk</th>
  <th>Breached</th><th>Met</th><th>Compliance</th><th>Avg resolution (h)</th></tr>
  ${list.map((x) => `<tr><td>${esc(x[key])}</td><td align="right">${x.total}</td><td align="right">${x.open}</td>
  <td align="right">${x.at_risk}</td><td align="right">${x.breached}</td><td align="right">${x.met}</td>
  <td align="right">${pct(x.compliance_pct)}</td><td align="right">${num(x.avg_resolution_hours)}</td></tr>`).join('')
    || '<tr><td colspan="8">No requests in this period</td></tr>'}
</table>`;

const html = `<div style="font-family:Arial,sans-serif;font-size:14px">
<p>SLA report for requests created ${esc(r.period_label)}.</p>
<table cellspacing="0"><tr>
  ${kpi('Requests', t.total)}${kpi('Open', t.open)}${kpi('At risk (open)', t.at_risk, '#b45309')}
  ${kpi('Breached', t.breached, '#b91c1c')}${kpi('SLA compliance', pct(t.compliance_pct), '#15803d')}
</tr></table>
${table('By department', r.by_department, 'department', 'Department')}
${table('By priority', r.by_priority, 'priority', 'Priority')}
${table('By category', r.by_category, 'category', 'Category')}
<p style="color:#6b7280;font-size:12px">Compliance = requests that met their SLA / requests whose SLA outcome is known
(closed, or still open past due). Open requests that are not yet due are not counted.</p>
<p><a href="${esc(r.queue_url)}">Open the Service Desk</a></p></div>`;

return [{
  json: {
    from: r.mail_from,
    to: r.recipients,
    subject: `[Service Desk] SLA report: ${pct(t.compliance_pct)} compliance, ${t.breached} breached, ${t.open} open`,
    html,
  },
}];
